public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

// Initialize a boolean array to keep track of visited n-tersections
boolean[] visited = new boolean[n];

// Initialize a Queue to hold the n-tersections to visit
Queue<int[]> queue = new LinkedList<>();

// Add the starting n-tersection to the Queue
queue.add(start);

// While the Queue is not empty
while (!queue.isEmpty()) {

// Get the next n-tersection to visit
int[] current = queue.remove();

// Mark the current n-tersection as visited
visited[current[0] * n + current[1]] = true;

// If the current n-tersection is the ending n-tersection, return "can be travelled"
if (Arrays.equals(current, end)) {
return "can be travelled";
}

// Loop through the paths between adjacent n-tersections
for (int[] path : paths) {

// If the path is not visited and it is going towards the ending n-tersection, add it to the Queue
if (!visited[path[0] * n + path[1]] && path[0] == current[0] && path[1] == current[1] + 1) {
queue.add(path);
}

// If the path is not visited and it is going towards the starting n-tersection, add it to the Queue
else if (!visited[path[0] * n + path[1]] && path[0] == current[0] && path[1] == current[1] - 1) {
queue.add(path);
}
}
}

// If the Queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
return "cannot be travelled";
}

