public int findMinFibonacciNumbers(int k) {
  // Edge case: k is negative
  if (k < 0) {
    throw new IllegalArgumentException("k must be non-negative");
  }

  // Initialize the Fibonacci sequence
  List<Integer> fibSequence = new ArrayList<>();
  fibSequence.add(0);
  fibSequence.add(1);

  // Loop until the sum of the Fibonacci sequence is greater than or equal to k
  while (fibSequence.get(fibSequence.size() - 1) + fibSequence.get(fibSequence.size() - 2) < k) {
    fibSequence.add(fibSequence.get(fibSequence.size() - 1) + fibSequence.get(fibSequence.size() - 2));
  }

  // Find the minimum number of Fibonacci numbers whose sum is k
  int minFibs = Integer.MAX_VALUE;
  for (int i = 0; i < fibSequence.size(); i++) {
    int sum = 0;
    for (int j = i; j < fibSequence.size(); j++) {
      sum += fibSequence.get(j);
      if (sum == k) {
        minFibs = Math.min(minFibs, j - i + 1);
        break;
      }
    }
  }

  return minFibs;
}

