    int[] order = new int[total];
    int index = 0;

    // First row
    for (int i = 0; i < cols; i++) {
        order[index] = mat[0][i];
        index++;
    }

    // Middle rows
    for (int i = 1; i < rows - 1; i++) {
        for (int j = 0; j < cols; j++) {
            order[index] = mat[i][j];
            index++;
        }
    }

    // Last row
    for (int i = cols - 1; i >= 0; i--) {
        order[index] = mat[rows - 1][i];
        index++;
    }

    return order;
}

