        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
        }
        previousChar = c;
    }

    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        String str = String.valueOf(i);
        int index = result.size() - 1;
        while (index >= 0 && result.get(index) > str.charAt(0)) {
            index--;
        }
        result.add(index + 1, i);
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    Set<Integer> uniqueNums = new HashSet<Integer>();
    for (int num : nums) {
        uniqueNums.add(num);
    }

    int sum = 0;
    for (int num : uniqueNums) {
        sum += num;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        int sum = i * i;
        if (sum > n) {
            break;
        }
        int remaining = n - sum;
        if (remaining == 0) {
            minSquares = 1;
        } else {
            int minRemainingSquares = minPerfectSquareSum(remaining);
            if (minRemainingSquares < minSquares) {
                minSquares = minRemainingSquares;
            }
        }
    }
    return minSquares;
}

public static String reverseWords(String s) {
  String[] words = s.split(" ");
  for (int i = 0; i < words.length; i++) {
    char[] word = words[i].toCharArray();
    for (int j = 0; j < word.length / 2; j++) {
      char temp = word[j];
      word[j] = word[word.length - j - 1];
      word[word.length - j - 1] = temp;
    }
    words[i] = new String(word);
  }
  return String.join(" ", words);
}
